INSERT INTO "settings" ("key", "draft", "published")
SELECT 'careers', v."value", v."value"
FROM (
  SELECT jsonb_build_object(
    'recipients', COALESCE(
      (SELECT "published"->'recipients' FROM "settings" WHERE "key" = 'leads'),
      '["HR@securitypartnersltd.com"]'::jsonb
    ),
    'retentionMonths', 12
  ) AS "value"
) AS v
WHERE EXISTS (SELECT 1 FROM "pages" WHERE "key" = 'home')
  AND NOT EXISTS (SELECT 1 FROM "settings" WHERE "key" = 'careers');
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.sp_with_careers_link("nav" jsonb) RETURNS jsonb AS $$
  SELECT CASE
    WHEN "nav" IS NULL OR jsonb_typeof("nav"->'headerLinks') <> 'array' THEN "nav"
    WHEN EXISTS (
      SELECT 1 FROM jsonb_array_elements("nav"->'headerLinks') AS l("value")
      WHERE l."value"->>'href' = '/careers'
    ) THEN "nav"
    ELSE jsonb_set("nav", '{headerLinks}', (
      SELECT jsonb_agg(x."value" ORDER BY x."pos")
      FROM (
        SELECT e."value", e."ord"::numeric AS "pos"
        FROM jsonb_array_elements("nav"->'headerLinks') WITH ORDINALITY AS e("value", "ord")
        UNION ALL
        SELECT '{"label": "Careers", "href": "/careers"}'::jsonb,
          COALESCE(
            (SELECT min(c."ord") FROM jsonb_array_elements("nav"->'headerLinks') WITH ORDINALITY AS c("value", "ord")
             WHERE c."value"->>'href' = '/contact') - 0.5,
            jsonb_array_length("nav"->'headerLinks') + 1
          )
      ) AS x
    ))
  END
$$ LANGUAGE sql IMMUTABLE;
--> statement-breakpoint
UPDATE "settings"
SET "draft" = pg_temp.sp_with_careers_link("draft"),
    "published" = pg_temp.sp_with_careers_link("published")
WHERE "key" = 'navigation';
